revoke all on function public.person_name_norm(text) from public, anon, authenticated, service_role;
grant execute on function public.person_name_norm(text) to authenticated, service_role;          -- the name trigger runs as the writer
revoke all on function public.person_name_problem(text) from public, anon, authenticated, service_role;
grant execute on function public.person_name_problem(text) to authenticated, service_role;
revoke all on function public.person_name_message(text, text) from public, anon, authenticated, service_role;
grant execute on function public.person_name_message(text, text) to authenticated, service_role;
